import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

fn make() -> conc.Mutex<Int64> {
    return conc.Mutex(41)
}

fn bump(m: conc.Mutex<Int64>) -> Int64 {
    let _ = m.set(m.get() + 1i64)
    return m.get()
}

fn viaLet() -> Int64 {
    let m = make()
    return bump(m)
}

fn viaArg() -> Int64 {
    return bump(make())
}

pub fn main() effect io -> Result<(), AppError> {
    let m = make()
    io.println("main ${bump(m)}")
    io.println("let ${viaLet()}")
    io.println("arg ${viaArg()}")
    return Ok(())
}
